use std::process;

const DEFAULT_COUNT: i32 = 15;

pub fn parse_count<I>(args: I) -> i32
where
    I: IntoIterator<Item = String>,
{
    let args: Vec<String> = args.into_iter().collect();
    let mut count = DEFAULT_COUNT;

    if args.len() > 1 && args[1] == "--a" {
        let raw_value = match args.get(2) {
            Some(value) => value.as_str(),
            None => abort_logic_error("basic_string::_S_construct null not valid"),
        };

        count = parse_cpp_i32(raw_value);
    }

    count
}

fn parse_cpp_i32(input: &str) -> i32 {
    let bytes = input.as_bytes();
    let mut index = 0usize;

    while index < bytes.len() && bytes[index].is_ascii_whitespace() {
        index += 1;
    }

    let mut sign = 1i128;
    if index < bytes.len() {
        match bytes[index] {
            b'+' => index += 1,
            b'-' => {
                sign = -1;
                index += 1;
            }
            _ => {}
        }
    }

    let digit_start = index;
    let mut value = 0i128;

    while index < bytes.len() && bytes[index].is_ascii_digit() {
        value = (value * 10) + i128::from(bytes[index] - b'0');
        index += 1;
    }

    if index == digit_start {
        abort_stoi("std::invalid_argument");
    }

    let signed_value = sign * value;
    if signed_value < i32::MIN as i128 || signed_value > i32::MAX as i128 {
        abort_stoi("std::out_of_range");
    }

    signed_value as i32
}

fn abort_logic_error(message: &str) -> ! {
    eprintln!("terminate called after throwing an instance of 'std::logic_error'");
    eprintln!("  what():  {message}");
    process::abort();
}

fn abort_stoi(exception_name: &str) -> ! {
    eprintln!("terminate called after throwing an instance of '{exception_name}'");
    eprintln!("  what():  stoi");
    process::abort();
}

#[cfg(test)]
mod tests {
    use super::parse_count;

    #[test]
    fn keeps_default_without_flag() {
        let args = vec!["test15".to_owned(), "ignored".to_owned()];
        assert_eq!(parse_count(args), 15);
    }

    #[test]
    fn parses_flag_value() {
        let args = vec!["test15".to_owned(), "--a".to_owned(), "5".to_owned()];
        assert_eq!(parse_count(args), 5);
    }

    #[test]
    fn matches_stoi_prefix_parsing() {
        let args = vec!["test15".to_owned(), "--a".to_owned(), "12abc".to_owned()];
        assert_eq!(parse_count(args), 12);
    }

    #[test]
    fn handles_negative_values() {
        let args = vec!["test15".to_owned(), "--a".to_owned(), "-3".to_owned()];
        assert_eq!(parse_count(args), -3);
    }
}

