use super::hopscotch_map::HopscotchMap;

pub fn count_equal_range_entries(count: i32) -> i32 {
    let mut map = HopscotchMap::new();

    for i in 0..count {
        map.insert((i, i * 12));
    }

    map.equal_range(&(count / 2)).count() as i32
}

#[cfg(test)]
mod tests {
    use super::count_equal_range_entries;

    #[test]
    fn matches_reference_examples() {
        assert_eq!(count_equal_range_entries(15), 1);
        assert_eq!(count_equal_range_entries(0), 0);
        assert_eq!(count_equal_range_entries(1), 1);
        assert_eq!(count_equal_range_entries(2), 1);
        assert_eq!(count_equal_range_entries(5), 1);
    }

    #[test]
    fn handles_negative_counts() {
        assert_eq!(count_equal_range_entries(-3), 0);
    }
}
